UPDATE pcd_recent_access_table
SET ra_accessed_at = #{ra_accessed_at}
WHERE ra_user_id = #{ra_user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND ra_access_type = #{ra_access_type}
  AND (
      ra_space_id = #{ra_space_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
      OR (#{personalSpace}=true AND ra_space_id IS NULL)
  )
  AND COALESCE(ra_access_source, 'space') = COALESCE(#{ra_access_source}, 'space')
  AND (
      (ra_access_source = 'share' AND ra_share_resource_id = #{ra_share_resource_id})
      OR
      (ra_file_id = #{ra_file_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
       AND #{ra_file_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} IS NOT NULL)
      OR
      (ra_node_id = #{ra_node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
       AND #{ra_node_id,typeHandler=org.project.util.UUIDBinaryTypeHandler} IS NOT NULL)
  )
ORDER BY ra_accessed_at DESC
LIMIT 1

