DELETE FROM pcd_recent_access_table
WHERE ra_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
  AND ra_access_type = #{access_type}
  AND ra_id NOT IN (
      SELECT ra_id FROM (
          SELECT ra_id FROM pcd_recent_access_table
          WHERE ra_user_id = #{user_id,typeHandler=org.project.util.UUIDBinaryTypeHandler}
            AND ra_access_type = #{access_type}
          ORDER BY ra_accessed_at DESC
          LIMIT #{keep_count}
      ) AS keep
  )

